{"implementation":"def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    failures = {}
    successes = []
    for i, t in enumerate(trials):
        entry = {'last_trial': i, 'reflection': t['reflection'], 'signature': t['signature'], 'success': t['success']}
        if t['success'] is False:
            failures[t['signature']] = entry
        else:
            successes.append(entry)
    cand = list(failures.values()) + successes
    cand.sort(key=lambda e: (e['success'], -e['last_trial'], e['signature']))
    sel = cand[:capacity]
    sel.sort(key=lambda e: e['last_trial'])
    mem = []
    sig = []
    for e in sel:
        mem.append(e)
        sig.append(e['signature'])
    return {'memory': mem, 'signatures': sig}
"}
